-- V8__embeddings_1536_with_model.sql
-- OpenAI text-embedding-3-small produces 1536-dimensional vectors. Vectors from different models live in
-- different spaces and must never be compared, so each row records the model that produced it; startup
-- reconciliation re-embeds any note whose vector is missing or came from another model.

DROP INDEX IF EXISTS idx_note_embeddings_vector;

-- The old 384-dim mock vectors cannot be cast to 1536 dims; they are regenerated by the job queue.
TRUNCATE note_embeddings;

ALTER TABLE note_embeddings ALTER COLUMN embedding TYPE vector(1536);
ALTER TABLE note_embeddings ADD COLUMN model VARCHAR(100) NOT NULL DEFAULT 'legacy';

CREATE INDEX idx_note_embeddings_vector ON note_embeddings USING hnsw (embedding vector_cosine_ops);
